=== endpoints.js（全文）===
/**
 * Endpoint 页（列表 + 详情：运行时 / 机器锁 / MCP 接入 / 任务队列 / 配置域）
 *
 * 对应端点：``GET /endpoints``、``POST /endpoints``、``GET|PATCH|DELETE
 * /endpoints/{id}``、``GET /endpoints/{id}/status``、``GET
 * /endpoints/{id}/lock``（+ ``POST .../lock/force-unlock``）、``GET
 * /endpoints/{id}/mcp``、``GET /endpoints/{id}/tasks``（+ ``POST
 * /tasks``、``POST /tasks/{taskId}/cancel|restart``）。
 *
 * 任务详情的完整视图（output/runSummary/…）在 Task 页；本页任务行的
 * 「详情」按钮跳转到 ``#/tasks?focus=<taskId>``。
 *
 * CSP 约束：模板只引属性/方法名；行视图模型与展示文本在 JS 侧预计算。
 */

(function () {
  'use strict';

  window.adminEndpoints = {
    // ── 列表 ──
    endpoints: [],
    endpointRows: [],
    detail: null,
    skills: [],
    showAdd: false,
    showCreated: false,
    created: null,
    addForm: { kind: 'computer-use', name: '', owner: '', env: '', labels: '' },

    // ── 详情 ──
    showEdit: false,
    editForm: { name: '', owner: '', env: '', labels: '' },
    showNewTask: false,
    newTaskForm: { prompt: '', model: '', skills: [], sessionMode: 'new', fromTask: '' },
    taskWarnings: [],

    // ── 生命周期 ──

    enterEndpoints() {
      if (this.route.focus) this.loadEndpointDetail(this.route.focus);
      else this.loadEndpointList();
    },

    refreshEndpoints() {
      if (this.route.focus) this.loadEndpointDetail(this.route.focus);
      else this.loadEndpointList();
    },

    loadEndpointList() {
      window.adminApi.get('/skills').then((r) => {
        this.skills = (r && r.items) || [];
      }).catch(() => {
        this.skills = [];
      });
      window.adminApi.get('/endpoints').then((list) => {
        var rows = list || [];
        this.endpoints = rows;
        this.endpointRows = rows.map((cfg) => this.buildEndpointRow(cfg, null));
        this.meta = '共 ' + rows.length + ' 节点 · 更新于 ' + new Date().toLocaleTimeString();
        this.error = '';
        this.loading = false;
        return Promise.all(rows.map((cfg) => this.loadEndpointStatus(cfg)));
      }).catch((e) => {
        this.error = '请求失败：' + this.errText(e);
        this.loading = false;
      });
    },

    loadEndpointStatus(cfg) {
      var id = encodeURIComponent(cfg.endpointId);
      return window.adminApi.get('/endpoints/' + id + '/status').then((status) => {
        var idx = this.endpointRows.findIndex(function (r) { return r.id === cfg.endpointId; });
        if (idx >= 0) this.endpointRows.splice(idx, 1, this.buildEndpointRow(cfg, status));
      }).catch(() => {});
    },

    /** 列表卡片视图模型（CSP：模板只读字段）。 */
    buildEndpointRow(cfg, status) {
      var state = (status && status.state) || 'offline';
      var cap = status && status.capability;
      var capTags = [];
      if (cap) {
        if (cap.os) capTags.push(cap.os);
        if (cap.arch) capTags.push(cap.arch);
        if (cap.extras && cap.extras.cua_driver) capTags.push('cua ' + cap.extras.cua_driver);
        if (cap.extras && cap.extras.macos) capTags.push('macOS ' + cap.extras.macos);
      }
      return {
        id: cfg.endpointId,
        name: cfg.name || cfg.endpointId,
        kind: cfg.kind || '',
        dotCls: 'dot ' + state,
        owner: cfg.owner || '—',
        env: cfg.env || '—',
        labels: cfg.labels || [],
        instanceId: (status && status.instanceId) || '—',
        sessionsText: ((status && status.activeSessions) || 0) + ' 活跃',
        connectedText: this.fmtTime(status && status.connectedAt),
        pongText: this.fmtTime(status && status.lastPongAt),
        createdText: this.fmtTime(cfg.createdAt),
        updatedText: this.fmtTime(cfg.updatedAt),
        capTags: capTags,
        kindMismatch: !!(cap && cap.kindMatch === false),
        capabilityMissing: !cap,
        mcpUrl: this.mcpUrl(cfg.endpointId)
      };
    },

    /** 概览 chips（节点数 / 在线数 / 会话总数）。 */
    get summaryChips() {
      var online = 0;
      var sessions = 0;
      this.endpointRows.forEach(function (r) {
        if (r.dotCls.indexOf('online') >= 0) online += 1;
      });
      this.endpoints.forEach(function (cfg, i) {
        var row = this.endpointRows[i];
        sessions += row && row.sessionsText ? parseInt(row.sessionsText, 10) || 0 : 0;
      }, this);
      return [
        { k: '节点', v: String(this.endpoints.length) },
        { k: '在线', v: String(online) },
        { k: '会话', v: String(sessions) }
      ];
    },

    /** skill 行视图模型（含勾选态；勾选来自 newTaskForm.skills）。 */
    get skillRows() {
      var self = this;
      var selected = this.newTaskForm.skills;
      return this.skills.map(function (s) {
        var key = (s.sourceName || s.gitSourceId || '') + ':' + s.path;
        var checked = selected.some(function (row) { return row.key === key; });
        return {
          key: key,
          name: (s.manifest && s.manifest.name) || s.name,
          sourceName: s.sourceName || s.gitSourceId || '',
          path: s.path,
          version: self.shortSha(s.commitSha),
          status: s.error || '可用',
          checked: checked
        };
      });
    },

    // ── 列表：导航与操作 ──

    openEndpoint(event) {
      var id = event.currentTarget.dataset.id;
      location.hash = '#/endpoints?focus=' + encodeURIComponent(id);
    },

    backToList() {
      location.hash = '#/endpoints';
    },

    toggleAdd() {
      this.showAdd = !this.showAdd;
    },

    submitAdd(event) {
      event.preventDefault();
      var body = {
        kind: this.addForm.kind.trim() || 'computer-use',
        name: this.addForm.name.trim(),
        owner: this.addForm.owner.trim(),
        env: this.addForm.env.trim(),
        labels: this.splitLabels(this.addForm.labels)
      };
      window.adminApi.post('/endpoints', body).then((created) => {
        this.created = created;
        this.showCreated = true;
        this.showAdd = false;
        this.addForm = { kind: 'computer-use', name: '', owner: '', env: '', labels: '' };
        this.loadEndpointList();
      }).catch((e) => {
        window.alert('添加失败：' + this.errText(e));
      });
    },

    closeCreated() {
      this.showCreated = false;
      this.created = null;
    },

    // ── 详情 ──

    loadEndpointDetail(endpointId) {
      var id = encodeURIComponent(endpointId);
      this.loading = true;
      Promise.all([
        window.adminApi.get('/endpoints/' + id).catch(() => null),
        window.adminApi.get('/endpoints/' + id + '/status').catch(() => null),
        window.adminApi.get('/endpoints/' + id + '/lock').catch(() => null),
        window.adminApi.get('/endpoints/' + id + '/mcp').catch(() => null),
        window.adminApi.get('/endpoints/' + id + '/tasks').catch(() => [])
      ]).then((parts) => {
        var cfg = parts[0];
        var status = parts[1];
        var lock = parts[2];
        var mcp = parts[3];
        var tasks = parts[4] || [];
        if (!cfg) {
          this.error = '节点不存在或已删除';
          location.hash = '#/endpoints';
          return;
        }
        this.detail = this.buildDetail(cfg, status, lock, mcp, tasks);
        this.meta = cfg.endpointId + ' · 更新于 ' + new Date().toLocaleTimeString();
        this.error = '';
        this.loading = false;
        if (!this.skills.length) {
          window.adminApi.get('/skills').then((r) => {
            this.skills = (r && r.items) || [];
          }).catch(() => {});
        }
      }).catch((e) => {
        this.error = '请求失败：' + this.errText(e);
        this.loading = false;
      });
    },

    /** 详情视图模型（CSP：模板只读字段，无运算符/实参）。 */
    buildDetail(cfg, status, lock, mcp, tasks) {
      var self = this;
      var state = (status && status.state) || 'offline';
      var cap = status && status.capability;
      var capTags = [];
      if (cap) {
        if (cap.os) capTags.push(cap.os);
        if (cap.arch) capTags.push(cap.arch);
        if (cap.extras && cap.extras.cua_driver) capTags.push('cua ' + cap.extras.cua_driver);
        if (cap.extras && cap.extras.macos) capTags.push('macOS ' + cap.extras.macos);
      }
      var locked = !!(lock && lock.locked);
      var holders = locked
        ? (lock.holders || []).map(function (h, i) {
            return { key: 'h' + i, kind: h.kind, taskId: h.taskId || '—', note: h.note || '—' };
          })
        : [];
      var queueRows = (tasks || []).map(function (t) {
        var node = t.plan && t.plan.nodes && t.plan.nodes[0];
        var active = self.isActiveTaskState(t.state);
        return {
          key: t.taskId,
          id: t.taskId,
          state: t.state,
          stateCls: 'st ' + t.state,
          active: active,
          inactive: !active,
          activeCls: active ? 'st active' : 'st',
          queueText: t.queuePosition ? '#' + t.queuePosition : '',
          title: (node && node.userMessage) || t.taskId,
          timeText: self.fmtTime(t.createdAt)
        };
      });
      this.editForm = {
        name: cfg.name || '',
        owner: cfg.owner || '',
        env: cfg.env || '',
        labels: (cfg.labels || []).join(', ')
      };
      return {
        id: cfg.endpointId,
        name: cfg.name || cfg.endpointId,
        kind: cfg.kind || '',
        dotCls: 'dot ' + state,
        state: state,
        instanceId: (status && status.instanceId) || '—',
        sessionsText: ((status && status.activeSessions) || 0) + ' 活跃',
        connectedText: this.fmtTime(status && status.connectedAt),
        pongText: this.fmtTime(status && status.lastPongAt),
        capTags: capTags,
        capabilityMissing: !cap,
        ownerLabel: cfg.owner || '—',
        envLabel: cfg.env || '—',
        labels: cfg.labels || [],
        createdText: this.fmtTime(cfg.createdAt),
        updatedText: this.fmtTime(cfg.updatedAt),
        mcpUrl: this.mcpUrl(cfg.endpointId),
        mcpTransport: (mcp && mcp.transport) || 'streamable-http',
        mcpNote: (mcp && mcp.note) || '工具目录经 MCP tools/list 获取',
        lock: {
          locked: locked,
          lockId: locked ? lock.lockId : '',
          createdText: locked ? this.fmtTime(lock.createdAt) : '',
          expiresText: locked ? this.fmtTime(lock.expiresAt) : '',
          holders: holders
        },
        queue: queueRows,
        hasQueue: queueRows.length > 0,
        noQueue: queueRows.length === 0,
        lockUnlocked: !locked
      };
    },

    // ── 详情：编辑配置域 ──

    toggleEdit() {
      this.showEdit = !this.showEdit;
    },

    submitEdit(event) {
      event.preventDefault();
      var id = encodeURIComponent(this.route.focus);
      window.adminApi.patch('/endpoints/' + id, {
        name: this.editForm.name.trim(),
        owner: this.editForm.owner.trim(),
        env: this.editForm.env.trim(),
        labels: this.splitLabels(this.editForm.labels)
      }).then(() => {
        this.showEdit = false;
        this.loadEndpointDetail(this.route.focus);
      }).catch((e) => {
        window.alert('保存失败：' + this.errText(e));
      });
    },

    removeEndpoint(event) {
      event.preventDefault();
      var id = this.route.focus;
      if (!window.confirm('删除节点 ' + id + '？该操作不可恢复。')) return;
      window.adminApi.del('/endpoints/' + encodeURIComponent(id)).then(() => {
        location.hash = '#/endpoints';
      }).catch((e) => {
        window.alert('删除失败：' + this.errText(e));
      });
    },

    // ── 详情：机器锁 ──

    forceUnlock() {
      var id = this.route.focus;
      if (!window.confirm('强制解锁 ' + id + '？将清掉当前锁并断开该机全部 MCP 会话。')) return;
      var reason = window.prompt('强解原因（可选，会记入事件流水）：', '');
      var body = reason && reason.trim() ? { reason: reason.trim() } : {};
      window.adminApi.post('/endpoints/' + encodeURIComponent(id) + '/lock/force-unlock', body).then(() => {
        this.loadEndpointDetail(id);
      }).catch((e) => {
        window.alert('强制解锁失败：' + this.errText(e));
      });
    },

    // ── 详情：任务队列（新建 / 取消 / 重跑 / 跳详情） ──

    toggleNewTask() {
      this.showNewTask = !this.showNewTask;
    },

    toggleNewTaskSkill(event) {
      var key = event.currentTarget.dataset.key;
      var row = this.skillRows.find(function (r) { return r.key === key; });
      if (!row) return;
      var i = this.newTaskForm.skills.findIndex(function (s) { return s.key === key; });
      if (i >= 0) this.newTaskForm.skills.splice(i, 1);
      else this.newTaskForm.skills.push({ key: key, sourceName: row.sourceName, path: row.path });
    },

    submitTask(event) {
      event.preventDefault();
      var f = this.newTaskForm;
      if (f.sessionMode !== 'new' && !f.fromTask.trim()) {
        window.alert('续用 / fork 需要选择来源 Task');
        return;
      }
      var spec = {
        input: { prompt: { text: f.prompt.trim() } },
        output: { schema: { type: 'object' } },
        capabilities: {
          environments: [{ name: 'mac', kind: 'computer-use' }],
          skills: f.skills.map(function (s) { return { source: s.sourceName, path: s.path }; })
        }
      };
      if (f.model.trim()) spec.model = f.model.trim();
      var body = { spec: spec, endpoints: { mac: this.route.focus } };
      if (f.sessionMode !== 'new') body.session = { fromTask: f.fromTask.trim(), mode: f.sessionMode };
      window.adminApi.post('/tasks', body).then((res) => {
        this.taskWarnings = (res && res.warnings) || [];
        this.showNewTask = false;
        this.newTaskForm = { prompt: '', model: '', skills: [], sessionMode: 'new', fromTask: '' };
        this.loadEndpointDetail(this.route.focus);
      }).catch((e) => {
        window.alert('派发失败：' + this.errText(e));
      });
    },

    cancelTask(event) {
      window.adminTasks.cancelTask.call(this, event);
    },

    restartTask(event) {
      window.adminTasks.restartTask.call(this, event);
    },

    openTaskFromEndpoint(event) {
      var id = event.currentTarget.dataset.taskId;
      location.hash = '#/tasks?focus=' + encodeURIComponent(id);
    },

    // ── 展示辅助 ──

    /** 列表/详情互斥（模板用；CSP 禁运算符）。 */
    get endpointListVisible() {
      return this.isEndpointsPage && !this.route.focus;
    },

    get endpointDetailVisible() {
      return this.isEndpointsPage && !!this.route.focus;
    },

    get endpointEmpty() {
      return !this.endpointRows.length;
    },

    get editHidden() {
      return !this.showEdit;
    },

    get noSkills() {
      return !this.skillRows.length;
    },

    get taskWarningsVisible() {
      return this.taskWarnings.length > 0;
    },

    get taskWarningsText() {
      return '创建警告：' + this.taskWarnings.join('；');
    },

    mcpUrl(endpointId) {
      return location.origin + '/mcp/endpoints/' + endpointId;
    }
  };
})();

=== api.js ===
/**
 * 管理页 HTTP 出口与错误/格式化工具（经典脚本，暴露 window.adminApi）。
 *
 * 令牌来源（优先级）：
 * 1. 手填令牌（localStorage ``agentAppToken``，调试兜底——用于 SPA
 *    登录流不可用时的临时访问）；
 * 2. 认证层（``window.agentAppAuth``）：``enforced`` 走 PKCE bundle 并
 *    在 401 时强制刷新重试一次；``disabled`` 直通不发令牌。
 *
 * 错误统一归一为 ``{status, message}`` 的 Error：
 * - FastAPI 校验错误（``detail`` 为数组）逐条拼「位置：说明」；
 * - 字符串 ``detail`` 原样；
 * - 401 给「需要令牌或登录已失效」提示。
 */
(function () {
  'use strict';

  var TOKEN_STORAGE_KEY = 'agentAppToken';

  function manualToken() {
    return localStorage.getItem(TOKEN_STORAGE_KEY) || '';
  }

  /** FastAPI 错误体 → 可读文本（数组逐条拼行，字符串原样）。 */
  function errorText(data) {
    var detail = data && data.detail;
    if (Array.isArray(detail)) {
      return detail.map(function (item) {
        var loc = item && Array.isArray(item.loc) ? item.loc.join('.') : '';
        var msg = (item && item.msg) || JSON.stringify(item);
        return loc ? loc + '：' + msg : msg;
      }).join('\n');
    }
    return typeof detail === 'string' ? detail : '';
  }

  function statusError(url, status, data) {
    if (status === 401) return '需要令牌或令牌已过期（HTTP 401）';
    if (status === 403) return '权限不足或令牌 scope 不含该操作（HTTP 403）';
    return errorText(data) || url + ' → HTTP ' + status;
  }

  function rawFetch(url, init) {
    var token = manualToken();
    if (token) {
      var headers = Object.assign({}, (init && init.headers) || {}, { Authorization: 'Bearer ' + token });
      return fetch(url, Object.assign({}, init, { headers: headers }));
    }
    var auth = window.agentAppAuth;
    if (auth && typeof auth.authFetch === 'function') return auth.authFetch(url, init);
    return fetch(url, init);
  }

  async function request(method, url, body, opts) {
    var init = { method: method };
    var options = opts || {};
    if (body !== undefined && body !== null) {
      init.headers = { 'Content-Type': options.contentType || 'application/json' };
      init.body = options.contentType ? String(body) : JSON.stringify(body);
    }
    var r = await rawFetch(url, init);
    var text = await r.text();
    var data = null;
    if (text) {
      try {
        data = JSON.parse(text);
      } catch (e) {
        data = text;
      }
    }
    if (!r.ok) {
      var err = new Error(statusError(url, r.status, data));
      err.status = r.status;
      err.body = data;
      throw err;
    }
    return data;
  }

  window.adminApi = {
    tokenKey: TOKEN_STORAGE_KEY,
    manualToken: manualToken,
    get: function (url) { return request('GET', url, undefined); },
    post: function (url, body, opts) { return request('POST', url, body, opts); },
    put: function (url, body, opts) { return request('PUT', url, body, opts); },
    patch: function (url, body) { return request('PATCH', url, body); },
    del: function (url) { return request('DELETE', url, undefined); },
    errorText: errorText
  };
})();
=== app.js ===
/**
 * 管理页核心（顶栏 / 分页导航 / 登录门 / 轮询 / mixin 装配）
 *
 * 页面结构：``static/admin/index.html`` 是壳（登录门 + 顶栏 + 导航 +
 * 每页一个 ``<template x-if>``），本文件与 ``js/pages/*.js`` 以
 * ``Object.assign`` 合并成单一 Alpine 组件（每页一个文件、状态集中在
 * 本文件的 ``core`` 部分）。
 *
 * **CSP 约束（重要）**：页面使用 Alpine 的 CSP 构建
 * （``alpine.min.js`` 为 @alpinejs/csp，挂载 mh-auth 的
 * ``SecurityHeadersMiddleware`` 后 CSP 为 ``script-src 'self'`` /
 * ``style-src 'self'``，无 unsafe-eval/unsafe-inline）。因此：
 * - 模板表达式只能引用**属性/方法名**（可带点路径），不得使用运算符、
 *   字面量、函数实参（``a === b`` / ``f(x)`` / ``{...}`` 都会失败）；
 * - 事件处理写方法名（``@click="goPage"``），需要区分目标时用
 *   ``:data-*`` 传值、处理函数从 ``event.currentTarget.dataset`` 读；
 * - 展示用字符串一律在 JS 侧预计算（本文件与各页 mixin 的 getter 或
 *   行视图模型），模板只做 ``x-text="row.text"``；
 * - HTML 不用内联 ``style`` 属性（CSP 会拦），样式全部走
 *   ``admin.css`` 的 class。
 *
 * 令牌：优先手填令牌（调试兜底），否则走认证层（PKCE bundle /
 * disabled 直通）——见 ``js/core/api.js``。
 */
(function () {
  'use strict';

  var REFRESH_MS = 5000;

  /** UTC ISO → 本地时间文本；空值/非法值给占位。 */
  function fmtTime(iso) {
    if (!iso) return '—';
    var d = new Date(iso);
    return isNaN(d.getTime()) ? String(iso) : d.toLocaleString();
  }

  function pretty(x) {
    if (x === null || x === undefined) return '—';
    try {
      return JSON.stringify(x, null, 2);
    } catch (e) {
      return String(x);
    }
  }

  function splitLabels(s) {
    return String(s || '').split(',').map(function (x) { return x.trim(); }).filter(Boolean);
  }

  function shortSha(sha) {
    return sha ? String(sha).slice(0, 8) : '—';
  }

  /** 核心 mixin：状态 + 路由 + 登录门 + 顶栏 + 轮询。 */
  var core = {
    // ── 全局状态 ──
    route: { page: 'config', focus: '' },
    meta: '',
    error: '',
    loading: true,
    gate: { required: false, busy: false, subtitle: '正在读取认证引导配置…', error: '' },
    authInfo: { mode: 'disabled', authenticated: false, subject: '', badge: '认证未开启' },
    tokenBox: { open: false, draft: '', status: '未设置' },
    nav: { config: true, endpoints: true, apps: true, tasks: true },

    // ── 生命周期 ──

    init() {
      this.tokenBox.status = window.adminApi.manualToken() ? '已设置' : '未设置';
      this.parseHash();
      window.addEventListener('hashchange', () => this.parseHash());
      setInterval(() => {
        if (!document.hidden && !this.modalOpen) this.refreshPage();
      }, REFRESH_MS);
      this.bootstrapAuth();
    },

    /** 读引导配置 → 决定是否显示登录门；enforced 且未登录时不加载页面数据。 */
    bootstrapAuth() {
      window.agentAppAuth.loadSpaConfig().then((cfg) => {

:root {
  --bg: #0f141a; --panel: #161d26; --line: #232d3a; --text: #dbe4ee; --dim: #7d8ea3;
  --green: #3fb950; --gray: #6e7681; --red: #f85149; --blue: #58a6ff; --orange: #d29922;
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--text);
       font: 14px/1.5 -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif; }
[x-cloak] { display: none !important; }
header { display: flex; align-items: center; gap: 12px; padding: 14px 20px;
         border-bottom: 1px solid var(--line); position: sticky; top: 0; background: var(--bg); z-index: 2; }
header h1 { font-size: 16px; margin: 0; }
header .meta { color: var(--dim); font-size: 12px; }
button { background: var(--panel); color: var(--text); border: 1px solid var(--line);
         border-radius: 6px; padding: 4px 12px; cursor: pointer; font-size: 13px; }
button.refresh { margin-left: auto; }
button.primary { background: #1f3a5f; border-color: #2d4d78; color: #a5cdff; margin-left: 8px; }
button.danger { background: #3d1d1f; border-color: #6b2a2e; color: #ffb4ad; }
button.slim { padding: 1px 8px; font-size: 11px; }
.banner { background: #3d1d1f; color: #ffb4ad; padding: 8px 20px;
          border-bottom: 1px solid #6b2a2e; font-size: 13px; }
.banner.ok { background: #12331e; color: #7ee2a8; border-color: #1d4d2e; }
.summary { display: flex; gap: 12px; padding: 16px 20px 4px; flex-wrap: wrap; }
.chip { background: var(--panel); border: 1px solid var(--line); border-radius: 8px; padding: 8px 14px; }
.chip .k { color: var(--dim); font-size: 11px; }
.chip .v { font-size: 18px; font-weight: 600; }
.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(380px, 1fr));
        gap: 14px; padding: 14px 20px 40px; }
.card { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 14px 16px; }
.card.clickable { cursor: pointer; }
.card.clickable:hover { border-color: #33507a; }
.card .head, .detail-head { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.dot { width: 9px; height: 9px; border-radius: 50%; background: var(--gray); flex: none; }
.dot.online { background: var(--green); box-shadow: 0 0 6px var(--green); }
.dot.prebuilt { background: var(--gray); }
.dot.offline { background: var(--red); }
.card .title, .detail-head .title { font-weight: 600; }
.card .id, .detail-head .id { color: var(--dim); font-size: 12px; }
.kind { margin-left: auto; font-size: 11px; color: var(--blue);
        border: 1px solid var(--line); border-radius: 5px; padding: 1px 7px; }
.cardmeta { margin-top: 10px; font-size: 12px; color: var(--dim);
            display: grid; grid-template-columns: 64px 1fr; row-gap: 3px; }
.cardmeta b { color: var(--text); font-weight: 500; display: flex; gap: 5px;
              flex-wrap: wrap; align-items: center; }
.tag { background: #1d2836; border-radius: 4px; padding: 0 6px; font-size: 11px; }
.warn { color: var(--orange); }
.mcp { margin-top: 8px; font-size: 11px; color: var(--dim); word-break: break-all; }
.mcp code, .banner code { color: #79c0ff; }
.hint { margin-top: 8px; font-size: 11px; color: var(--dim); text-align: right; }
.empty { color: var(--dim); font-size: 12px; padding: 6px 2px; }
footer { color: var(--dim); font-size: 11px; text-align: center; padding: 10px; }

/* ── 详情页 ── */
.detail { padding: 14px 20px 40px; display: flex; flex-direction: column; gap: 14px; }
.detail-head .actions { margin-left: auto; display: flex; gap: 8px; }
.panel { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 14px 16px; }
h3.sec { margin: 0 0 10px; font-size: 12px; color: var(--dim); font-weight: 600; }
.secrow { display: flex; align-items: center; margin-bottom: 10px; }
.secrow h3.sec { margin: 0; flex: 1; }
h4 { margin: 0 0 6px; font-size: 12px; color: var(--dim); }
.task { display: flex; align-items: center; gap: 8px; padding: 5px 8px;
        border: 1px solid var(--line); border-radius: 6px; margin-bottom: 5px; font-size: 12px; }
.task.clickable { cursor: pointer; }
.task.clickable:hover { border-color: #33507a; }
.task .prompt { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1; }
.st { flex: none; font-size: 11px; border-radius: 4px; padding: 0 6px; }
.st.queued, .st.prebuilt { background: #21262d; color: var(--dim); }
.st.dispatching, .st.running, .st.verifying { background: #12233d; color: var(--blue); }
.st.done, .st.online { background: #12331e; color: var(--green); }
.st.failed, .st.offline { background: #3d1d1f; color: var(--red); }
.st.cancelled { background: #3a2c10; color: var(--orange); }
.pos { color: var(--dim); flex: none; }
.taskdetail { background: #10161d; border: 1px solid var(--line); border-radius: 6px;
              padding: 10px 12px; margin: 0 0 8px; }
pre { margin: 0; font-size: 12px; color: #a8d4ff; overflow-x: auto;
      white-space: pre-wrap; word-break: break-all; }
.secret { background: #10161d; border: 1px dashed #2d4d78; border-radius: 6px;
          padding: 10px 12px; color: #7ee2a8; font-size: 13px; }

/* ── 表单与弹层 ── */
.form { display: flex; flex-direction: column; gap: 8px; margin-top: 10px; }
.form input, .form textarea { background: #10161d; color: var(--text);
  border: 1px solid var(--line); border-radius: 6px; padding: 7px 10px; font-size: 13px; }
.form input:focus, .form textarea:focus { outline: none; border-color: #2d4d78; }
.formbtns { display: flex; gap: 8px; margin-top: 4px; }
.overlay { position: fixed; inset: 0; background: rgba(5, 8, 12, 0.75); z-index: 10;
           display: flex; align-items: center; justify-content: center; }
.modal { background: var(--panel); border: 1px solid var(--line); border-radius: 10px;
         padding: 18px 20px; width: min(480px, 92vw); max-height: 86vh; overflow-y: auto; }
.modal h3 { margin: 0 0 10px; font-size: 14px; }
.ok-text { color: var(--dim); font-size: 12px; margin: 0 0 8px; }

/* 新建任务：技能多选（目录行 → 全形态引用随任务下发） */
.skills { display: flex; flex-wrap: wrap; gap: 6px; }
.skillopt { display: inline-flex; align-items: center; gap: 4px; border: 1px solid var(--line, #ddd); border-radius: 4px; padding: 2px 8px; font-size: 12px; cursor: pointer; }
.skillopt code { color: var(--dim); }

/* 第二环：任务过滤/分页、会话选项与时间显示 */
.form.inline { flex-direction: row; flex-wrap: wrap; align-items: flex-end; }
.form select { background: #10161d; color: var(--text); border: 1px solid var(--line);
  border-radius: 6px; padding: 7px 10px; font-size: 13px; }
.form select:focus { outline: none; border-color: #2d4d78; }
.field { display: flex; flex-direction: column; gap: 4px; font-size: 12px; color: var(--dim); }
.cardmeta .time, .task .time { color: var(--dim); font-size: 11px; flex: none; }
.run { border-top: 1px dashed var(--line); margin-top: 8px; padding-top: 8px; }

/* ── 多页骨架：顶栏 / 分页导航 / 登录门 ── */
.topbar { display: flex; align-items: center; gap: 12px; padding: 10px 20px;
          border-bottom: 1px solid var(--line); position: sticky; top: 0;
          background: var(--bg); z-index: 3; flex-wrap: wrap; }
.brand { font-weight: 600; }
.badge { font-size: 11px; border: 1px solid var(--line); border-radius: 5px;
