.auth-card h2 { margin: 0 0 10px; font-size: 16px; }
.auth-card .meta { color: var(--dim); font-size: 12px; margin: 0 0 12px; }
.err-text { color: #ffb4ad; font-size: 12px; }

/* ── 配置页：左树 + 右编辑器 ── */
.cfg-wrap { display: grid; grid-template-columns: minmax(320px, 1fr) minmax(380px, 1.4fr);
            gap: 14px; padding: 12px 20px 20px; align-items: start; }
.cfg-row { display: flex; align-items: center; gap: 6px; padding: 3px 6px;
