{"content":"/**
 * Endpoint 页（列表 + 详情：运行时 / 机器锁 / MCP 接入 / 任务队列 / 配置域）
 *
 * 对应端点：``GET /endpoints``、``POST /endpoints``、``GET|PATCH|DELETE
 * /endpoints/{id}``、``GET /endpoints/{id}/status``、``GET|POST
 * /endpoints/{id}/lock``、``DELETE /endpoints/{id}/lock/{lockId}``（凭据
 * ``X-Release-Token`` 头）、``POST .../lock/force-unlock``、``GET
 * /endpoints/{id}/mcp``、``GET /endpoints/{id}/tasks``（+ ``POST
 * /tasks``、``POST /tasks/{taskId}/cancel|restart``）。
 *
 * 机器锁语义（与后端契约一致）：``lockId`` 全量可见（查看接口返回），
 * ``releaseToken`` 只在申请响应里出现一次（前端仅存内存、不进
 * localStorage）；外部申请只能新建（``holder.kind=manual``），复用是内部
 * 调度路径；被他锁时申请返回 ``409``，响应体带 ``holders`` 与
 * ``expiresAt``（本页用富体面板展示，不用 alert）。
 *
 * 面板级三态：``panels`` 记录每段（status/lock/mcp/tasks）的
 * ``idle|loading|ok|error``，失败原因记在 ``panelErr``——403 是权限不足、
 * 404 是资源不存在、其余是请求失败；**不能把失败静默成空态**（否则
 * 「未锁定」「无任务」会被误读为真实状态）。
 *
 * 任务详情的完整视图（output/runSummary/…）在 Task 页；本页任务行的
 * 「详情」按钮跳转到 ``#/tasks?focus=<taskId>``。
 *
 * CSP 约束：模板只引属性/方法名；行视图模型与展示文本在 JS 侧预计算。
 */

(function () {
  'use strict';

  var STALE_PONG_MS = 30000;
  var LOCK_MAX_SECONDS = 3600;
  var NOTE_MAX_CHARS = 200;
  var QUEUE_STATES = ['queued', 'dispatching', 'running', 'verifying', 'done', 'failed', 'cancelled'];
  var ACTIVE_STATES = ['queued', 'dispatching', 'running', 'verifying'];

  window.adminEndpoints = {
    // ── 列表 ──
    endpoints: [],
    endpointRows: [],
    detail: null,
    skills: [],
    showAdd: false,
    showCreated: false,
    created: null,
    addForm: { kind: 'computer-use', name: '', owner: '', env: '', labels: '' },

    // ── 详情 ──
    showEdit: false,
    editForm: { name: '', owner: '', env: '', labels: '' },
    showNewTask: false,
    newTaskForm: { prompt: '', model: '', skills: [], sessionMode: 'new', fromTask: '' },
    taskWarnings: [],

    // ── 详情：面板三态 ──
    panels: { status: 'idle', lock: 'idle', mcp: 'idle', tasks: 'idle' },
    panelErr: { status: '', lock: '', mcp: '', tasks: '' },

    // ── 详情：机器锁 ──
    lockForm: { open: false, maxDurationSeconds: LOCK_MAX_SECONDS, note: '', token: '' },
    lockAcquire: null,
    lockConflict: null,
    lockError: '',
    lockTip: '',

    // ── 详情：复制反馈 ──
    copyTip: '',

    // ── 详情：任务过滤 ──
    queueFilter: 'all',

    // ── 生命周期 ──

    enterEndpoints() {
      if (this.route.focus) this.loadEndpointDetail(this.route.focus);
      else this.loadEndpointList();
    },

    refreshEndpoints() {
      if (this.route.focus) this.loadEndpointDetail(this.route.focus);
      else this.loadEndpointList();
    },

    loadEndpointList() {
      window.adminApi.get('/skills').then((r) => {
        this.skills = (r && r.items) || [];
      }).catch(() => {
        this.skills = [];
      });
      window.adminApi.get('/endpoints').then((list) => {
        var rows = list || [];
        this.endpoints = rows;
        this.endpointRows = rows.map((cfg) => this.buildEndpointRow(cfg, null));
        this.meta = '共 ' + rows.length + ' 节点 · 更新于 ' + new Date().toLocaleTimeString();
        this.error = '';
        this.loading = false;
        return Promise.all(rows.map((cfg) => this.loadEndpointStatus(cfg)));
      }).catch((e) => {
        this.error = '请求失败：' + this.errText(e);
        this.loading = false;
      });
    },

    loadEndpointStatus(cfg) {
      var id = encodeURIComponent(cfg.endpointId);
      return window.adminApi.get('/endpoints/' + id + '/status').then((status) => {
        var idx = this.endpointRows.findIndex(function (r) { return r.id === cfg.endpointId; });
        if (idx >= 0) this.endpointRows.splice(idx, 1, this.buildEndpointRow(cfg, status));
      }).catch(() => {});
    },

    /** 列表卡片视图模型（CSP：模板只读字段）。 */
    buildEndpointRow(cfg, status) {
      var state = (status && status.state) || 'offline';
      var meta = this.stateMeta(status);
      return {
        id: cfg.endpointId,
        name: cfg.name || cfg.endpointId,
        kind: cfg.kind || '',
        dotCls: 'dot ' + state,
        stateBadge: meta.badge,
        stateBadgeCls: meta.badgeCls,
        owner: cfg.owner || '—',
        env: cfg.env || '—',
        labels: cfg.labels || [],
        instanceId: (status && status.instanceId) || '—',
        sessionsText: ((status && status.activeSessions) || 0) + ' 活跃',
        sessionsHot: !!((status && status.activeSessions) || 0),
        connectedText: this.fmtTime(status && status.connectedAt),
        pongText: this.fmtTime(status && status.lastPongAt),
        pongAgoText: this.agoText(status && status.lastPongAt),
        pongStale: this.isStale(status && status.lastPongAt),
        createdText: this.fmtTime(cfg.createdAt),
        updatedText: this.fmtTime(cfg.updatedAt),
        capTags: meta.capTags,
        kindMismatch: meta.kindMismatch,
        capabilityMissing: meta.capabilityMissing,
        mcpUrl: this.mcpUrl(cfg.endpointId)
      };
    },

    /** 状态徽标与能力标签（列表/详情共用，避免两处漂移）。 */
    stateMeta(status) {
      var cap = status && status.capability;
      var capTags = [];
      if (cap) {
        if (cap.os) capTags.push(cap.os);
        if (cap.arch) capTags.push(cap.arch);
        if (cap.extras && cap.extras.cua_driver) capTags.push('cua ' + cap.extras.cua_driver);
        if (cap.extras && cap.extras.macos) capTags.push('macOS ' + cap.extras.macos);
      }
      var state = (status && status.state) || 'offline';
      var badge = '状态未知';
      if (state === 'online') badge = '在线';
      else if (state === 'offline') badge = '离线';
      return {
        state: state,
        badge: badge,
        badgeCls: 'badge st ' + state,
        capTags: capTags,
        kindMismatch: !!(cap && cap.kindMatch === false),
        capabilityMissing: !cap
      };
    },

    /** 概览 chips（节点数 / 在线数 / 会话总数）。 */
    get summaryChips() {
      var online = 0;
      var sessions = 0;
      this.endpointRows.forEach(function (r) {
        if (r.dotCls.indexOf('online') >= 0) online += 1;
      });
      this.endpoints.forEach(function (cfg, i) {
        var row = this.endpointRows[i];
        sessions += row && row.sessionsText ? parseInt(row.sessionsText, 10) || 0 : 0;
      }, this);
      return [
        { k: '节点', v: String(this.endpoints.length) },
        { k: '在线', v: String(online) },
        { k: '会话', v: String(sessions) }
      ];
    },

    /** skill 行视图模型（含勾选态；勾选来自 newTaskForm.skills）。 */
    get skillRows() {
      var self = this;
      var selected = this.newTaskForm.skills;
      return this.skills.map(function (s) {
        var key = (s.sourceName || s.gitSourceId || '') + ':' + s.path;
        var checked = selected.some(function (row) { return row.key === key; });
        return {
          key: key,
          name: (s.manifest && s.manifest.name) || s.name,
          sourceName: s.sourceName || s.gitSourceId || '',
          path: s.path,
          version: self.shortSha(s.commitSha),
          status: s.error || '可用',
          checked: checked
        };
      });
    },

    // ── 列表：导航与操作 ──

    openEndpoint(event) {
      var id = event.currentTarget.dataset.id;
      location.hash = '#/endpoints?focus=' + encodeURIComponent(id);
    },

    backToList() {
      location.hash = '#/endpoints';
    },

    toggleAdd() {
      this.showAdd = !this.showAdd;
    },

    submitAdd(event) {
      event.preventDefault();
      var body = {
        kind: this.addForm.kind.trim() || 'computer-use',
        name: this.addForm.name.trim(),
        owner: this.addForm.owner.trim(),
        env: this.addForm.env.trim(),
        labels: this.splitLabels(this.addForm.labels)
      };
      window.adminApi.post('/endpoints', body).then((created) => {
        this.created = created;
        this.showCreated = true;
        this.showAdd = false;
        this.addForm = { kind: 'computer-use', name: '', owner: '', env: '', labels: '' };
        this.loadEndpointList();
      }).catch((e) => {
        window.alert('添加失败：' + this.errText(e));
      });
    },

    closeCreated() {
      this.showCreated = false;
      this.created = null;
    },

    // ── 详情 ──

    /** 详情装配：主配置缺失（404）回列表；其余四段各自记三态，失败不静默成空。 */
    loadEndpointDetail(endpointId) {
      var id = encodeURIComponent(endpointId);
      this.loading = true;
      this.error = '';
      this.lockError = '';
      this.lockTip = '';
      this.copyTip = '';
      this.lockConflict = null;
      this.setPanel('status', 'loading');
      this.setPanel('lock', 'loading');
      this.setPanel('mcp', 'loading');
      this.setPanel('tasks', 'loading');

      window.adminApi.get('/endpoints/' + id).then((cfg) => {
        if (!cfg) {
          this.error = '节点不存在或已删除';
          location.hash = '#/endpoints';
          return;
        }
        this.detail = this.buildDetail(cfg, null, null, null, null);
        this.meta = cfg.endpointId + ' · 更新于 ' + new Date().toLocaleTimeString();
        this.error = '';
        this.loading = false;
        this.connectPanels(id, cfg);
        if (!this.skills.length) {
          window.adminApi.get('/skills').then((r) => {
            this.skills = (r && r.items) || [];
          }).catch(() => {});
        }
      }).catch((e) => {
        this.error = '请求失败：' + this.errText(e);
        this.loading = false;
      });
    },

    /** 四段详情数据各自请求；每段独立三态，403/404/其他分列原因。 */
    connectPanels(id, cfg) {
      var self = this;
      this.trackPanel('status', window.adminApi.get('/endpoints/' + id + '/status'), 'endpoint:read', function (status) {
        self.detail = self.buildDetail(cfg, status, self.detail ? self.detail.rawLock : null,
          self.detail ? self.detail.rawMcp : null, self.detail ? self.detail.rawTasks : null);
      });
      this.trackPanel('lock', window.adminApi.get('/endpoints/' + id + '/lock'), 'lock:read', function (lock) {
        self.detail = self.buildDetail(cfg, self.detail ? self.detail.rawStatus : null, lock,
          self.detail ? self.detail.rawMcp : null, self.detail ? self.detail.rawTasks : null);
      });
      this.trackPanel('mcp', window.adminApi.get('/endpoints/' + id + '/mcp'), 'endpoint:read', function (mcp) {
        self.detail = self.buildDetail(cfg, self.detail ? self.detail.rawStatus : null,
          self.detail ? self.detail.rawLock : null, mcp, self.detail ? self.detail.rawTasks : null);
      });
      this.trackPanel('tasks', window.adminApi.get('/endpoints/' + id + '/tasks'), 'task:read', function (tasks) {
        self.detail = self.buildDetail(cfg, self.detail ? self.detail.rawStatus : null,
          self.detail ? self.detail.rawLock : null, self.detail ? self.detail.rawMcp : null, tasks || []);
      });
    },

    setPanel(name, state) {
      this.panels = Object.assign({}, this.panels, {});
      this.panels[name] = state;
    },

    /** 面板请求包装：成功 → ok、失败 → error + 原因（不静默）。 */
    trackPanel(name, promise, scopeName, onOk) {
      this.setPanel(name, 'loading');
      return promise.then((data) => {
        onOk(data);
        this.setPanel(name, 'ok');
      }).catch((e) => {
        this.panelErr[name] = this.panelErrorText(e, scopeName);
        this.setPanel(name, 'error');
      });
    },

    panelErrorText(e, scopeName) {
      if (e && e.status === 403) return '权限不足（需 ' + scopeName + '）';
      if (e && e.status === 404) return '资源不存在';
      return '请求失败：' + this.errText(e);
    },

    /** 详情视图模型（CSP：模板只读字段，无运算符/实参）。 */
    buildDetail(cfg, status, lock, mcp, tasks) {
      var self = this;
      var meta = this.stateMeta(status);
      var locked = !!(lock && lock.locked);
      var lockId = locked ? lock.lockId : '';
      var mine = !!(locked && this.lockAcquire && this.lockAcquire.lockId === lockId);
      var holders = locked
        ? (lock.holders || []).map(function (h, i) {
            return {
              key: 'h' + i,
              kind: h.kind,
              kindText: h.kind === 'task' ? '内部调度' : '外部人工',
              taskId: h.taskId ? this.shortSha(h.taskId) : '—',
              taskFull: h.taskId || '',
              note: h.note || '—'
            };
          }, this)
        : [];
      var queueRows = (tasks || []).map(function (t) {
        var node = t.plan && t.plan.nodes && t.plan.nodes[0];
        var active = self.isActiveTaskState(t.state);
        return {
          key: t.taskId,
          id: t.taskId,
          state: t.state,
          stateCls: 'st ' + t.state,
          active: active,
          inactive: !active,
          activeCls: active ? 'st active' : 'st',
          queueText: t.queuePosition ? '#' + t.queuePosition : '—',
          title: (node && node.userMessage) || t.taskId,
          timeText: self.fmtTime(t.createdAt)
        };
      });
      this.editForm = {
        name: cfg.name || '',
        owner: cfg.owner || '',
        env: cfg.env || '',
        labels: (cfg.labels || []).join(', ')
      };
      var badges = this.lockBadges(locked, lock, mine);
      return {
        id: cfg.endpointId,
        name: cfg.name || cfg.endpointId,
        kind: cfg.kind || '',
        dotCls: 'dot ' + meta.state,
        state: meta.state,
        stateBadge: meta.badge,
        stateBadgeCls: meta.badgeCls,
        instanceId: (status && status.instanceId) || '—',
        sessionsText: ((status && status.activeSessions) || 0) + ' 活跃',
        sessionsHot: !!((status && status.activeSessions) || 0),
        connectedText: this.fmtTime(status && status.connectedAt),
        pongText: this.fmtTime(status && status.lastPongAt),
        pongAgoText: this.agoText(status && status.lastPongAt),
        pongStale: this.isStale(status && status.lastPongAt),
        capTags: meta.capTags,
        kindMismatch: meta.kindMismatch,
        capabilityMissing: meta.capabilityMissing,
        ownerLabel: cfg.owner || '—',
        envLabel: cfg.env || '—',
        labels: cfg.labels || [],
        createdText: this.fmtTime(cfg.createdAt),
        updatedText: this.fmtTime(cfg.updatedAt),
        mcpUrl: this.mcpUrl(cfg.endpointId),
        mcpLockUrl: locked ? this.mcpUrl(cfg.endpointId) + '?lockId=' + lockId : '',
        mcpHasLock: locked,
        mcpTransport: (mcp && mcp.transport) || 'streamable-http',
        mcpNote: (mcp && mcp.note) || '工具目录经 MCP tools/list 获取',
        lock: {
          locked: locked,
          unlocked: !locked,
          mine: mine,
          others: locked && !mine,
          expired: badges.expired,
          stateText: badges.stateText,
          stateCls: badges.stateCls,
          lockId: lockId,
          createdText: locked ? this.fmtTime(lock.createdAt) : '',
          expiresText: locked ? this.fmtTime(lock.expiresAt) : '',
          remainingText: locked ? this.remainingText(lock.expiresAt) : '',
          holders: holders,
          hasHolders: holders.length > 0
        },
        queue: queueRows,
        queueTotal: queueRows.length,
        hasQueue: queueRows.length > 0,
        noQueue: queueRows.length === 0,
        // 原始数据留一份，供各段回填时重建视图模型（避免相互覆盖）。
        rawStatus: status,
        rawLock: lock,
        rawMcp: mcp,
        rawTasks: tasks
      };
    },

    /** 锁状态徽标：未锁定 / 已锁定·我持有 / 已锁定·他人持有 / 已过期。 */
    lockBadges(locked, lock, mine) {
      if (!locked) {
        return { expired: false, stateText: '未锁定', stateCls: 'badge st prebuilt' };
      }
      var expired = this.isPast(lock && lock.expiresAt);
      if (expired) return { expired: true, stateText: '已过期', stateCls: 'badge st cancelled' };
      if (mine) return { expired: false, stateText: '已锁定·我持有', stateCls: 'badge st running' };
      return { expired: false, stateText: '已锁定·他人持有', stateCls: 'badge st failed' };
    },

    // ── 详情：编辑配置域 ──

    toggleEdit() {
      this.showEdit = !this.showEdit;
    },

    submitEdit(event) {
      event.preventDefault();
      var id = encodeURIComponent(this.route.focus);
      window.adminApi.patch('/endpoints/' + id, {
        name: this.editForm.name.trim(),
        owner: this.editForm.owner.trim(),
        env: this.editForm.env.trim(),
        labels: this.splitLabels(this.editForm.labels)
      }).then(() => {
        this.showEdit = false;
        this.loadEndpointDetail(this.route.focus);
      }).catch((e) => {
        window.alert('保存失败：' + this.errText(e));
      });
    },

    removeEndpoint(event) {
      event.preventDefault();
      var id = this.route.focus;
      if (!window.confirm('删除节点 ' + id + '？该操作不可恢复。')) return;
      window.adminApi.del('/endpoints/' + encodeURIComponent(id)).then(() => {
        location.hash = '#/endpoints';
      }).catch((e) => {
        window.alert('删除失败：' + this.errText(e));
      });
    },

    // ── 详情：机器锁（查看 / 申请 / 释放 / 强解） ──

    /** 只重取锁面板（不重拉整页）。 */
    refreshLock() {
      var self = this;
      var id = encodeURIComponent(this.route.focus);
      this.trackPanel('lock', window.adminApi.get('/endpoints/' + id + '/lock'), 'lock:read', function (lock) {
        var d = self.detail;
        self.detail = self.buildDetailSelf(d, lock, d ? d.rawStatus : null);
      });
    },

    /** 锁面板回填（其余段保持不变）。 */
    buildDetailSelf(d, lock, status) {
      if (!d) return d;
      var cfg = {
        endpointId: d.id,
        name: d.name,
        kind: d.kind,
        owner: d.ownerLabel === '—' ? '' : d.ownerLabel,
        env: d.envLabel === '—' ? '' : d.envLabel,
        labels: d.labels,
        createdAt: null,
        updatedAt: null
      };
      var rebuilt = this.buildDetail(cfg, status, lock, d.rawMcp, d.rawTasks);
      rebuilt.createdText = d.createdText;
      rebuilt.updatedText = d.updatedText;
      return rebuilt;
    },

    toggleLockForm() {
      this.lockForm.open = !this.lockForm.open;
      this.lockError = '';
    },

    submitLock(event) {
      event.preventDefault();
      var secs = parseInt(this.lockForm.maxDurationSeconds, 10);
      if (!(secs >= 1 && secs <= LOCK_MAX_SECONDS)) {
        this.lockError = 'maxDurationSeconds 取值 1–' + LOCK_MAX_SECONDS;
        return;
      }
      var note = this.lockForm.note.trim();
      if (note.length > NOTE_MAX_CHARS) {
        this.lockError = 'note 不超过 ' + NOTE_MAX_CHARS + ' 字符';
        return;
      }
      var holder = { kind: 'manual' };
      if (note) holder.note = note;
      var id = this.route.focus;
      this.lockError = '';
      window.adminApi.post('/endpoints/' + encodeURIComponent(id) + '/lock', {
        maxDurationSeconds: secs,
        holder: holder
      }).then((res) => {
        this.lockAcquire = {
          lockId: res.lockId,
          releaseToken: res.releaseToken,
          expiresText: this.fmtTime(res.expiresAt)
        };
        this.lockForm.token = res.releaseToken;
        this.lockForm.open = false;
        this.lockForm.note = '';
        this.lockConflict = null;
        this.lockTip = '已申请锁：releaseToken 只显示一次，请立即保存。';
        this.loadEndpointDetail(id);
      }).catch((e) => {
        if (e && e.status === 409) this.lockConflict = this.buildConflict(e.body);
        else this.lockError = '申请失败：' + this.errText(e);
      });
    },

    /** 409 富体：谁持有、何时到期（不再用 alert 展示）。 */
    buildConflict(body) {
      var b = body || {};
      var holders = (b.holders || []).map(function (h, i) {
        return {
          key: 'c' + i,
          kind: h.kind,
          kindText: h.kind === 'task' ? '内部调度' : '外部人工',
          taskId: h.taskId ? this.shortSha(h.taskId) : '—',
          taskFull: h.taskId || '',
          note: h.note || '—'
        };
      }, this);
      return {
        detail: b.detail || '该机器已被其他持有者锁定',
        holders: holders,
        hasHolders: holders.length > 0,
        expiresText: this.fmtTime(b.expiresAt),
        remainingText: this.remainingText(b.expiresAt)
      };
    },

    closeLockConflict() {
      this.lockConflict = null;
    },

    releaseLock(event) {
      event.preventDefault();
      var id = this.route.focus;
      var lockId = this.detail && this.detail.lock.lockId;
      var token = (this.lockForm.token || '').trim();
      if (!lockId) {
        this.lockError = '该机当前无锁';
        return;
      }
      if (!token) {
        this.lockError = '请输入 releaseToken（只在申请时显示一次）';
        return;
      }
      if (!window.confirm('释放锁 ' + lockId + '？')) return;
      this.lockError = '';
      window.adminApi.del('/endpoints/' + encodeURIComponent(id) + '/lock/' + encodeURIComponent(lockId), {
        headers: { 'X-Release-Token': token }
      }).then(() => {
        this.lockAcquire = null;
        this.lockForm.token = '';
        this.lockTip = '已释放锁。';
        this.loadEndpointDetail(id);
      }).catch((e) => {
        if (e && e.status === 403) this.lockError = 'releaseToken 无效（HTTP 403）';
        else if (e && e.status === 404) this.lockError = '锁已不存在（可能已到期或已被释放）';
        else this.lockError = '释放失败：' + this.errText(e);
      });
    },

    forceUnlock() {
      var id = this.route.focus;
      if (!window.confirm('强制解锁 ' + id + '？将清掉当前锁并断开该机全部 MCP 会话。')) return;
      var reason = window.prompt('强解原因（可选，会记入事件流水）：', '');
      var body = reason && reason.trim() ? { reason: reason.trim() } : {};
      this.lockError = '';
      window.adminApi.post('/endpoints/' + encodeURIComponent(id) + '/lock/force-unlock', body).then(() => {
        this.lockAcquire = null;
        this.lockForm.token = '';
        this.lockTip = '已强制解锁并断开该机全部 MCP 会话。';
        this.loadEndpointDetail(id);
      }).catch((e) => {
        this.lockError = '强制解锁失败：' + this.errText(e);
      });
    },

    closeLockAcquire() {
      this.lockAcquire = null;
    },

    // ── 详情：复制（MCP 地址等；失败回退手选） ──

    copyText(text) {
      var self = this;
      if (!text) return;
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(function () {
          self.flashCopyTip('已复制');
        }).catch(function () {
          window.prompt('复制下面的内容：', text);
          self.flashCopyTip('已选中，请手动复制');
        });
        return;
      }
      window.prompt('复制下面的内容：', text);
      this.flashCopyTip('已选中，请手动复制');
    },

    flashCopyTip(text) {
      var self = this;
      this.copyTip = text;
      window.setTimeout(function () { self.copyTip = ''; }, 2500);
    },

    copyMcpUrl() {
      this.copyText(this.detail && this.detail.mcpUrl);
    },

    copyMcpLockUrl() {
      this.copyText(this.detail && this.detail.mcpLockUrl);
    },

    copyLockId() {
      this.copyText(this.detail && this.detail.lock.lockId);
    },

    // ── 详情：任务过滤 ──

    setQueueFilter(event) {
      this.queueFilter = event.currentTarget.dataset.key || 'all';
    },

    clearQueueFilter() {
      this.queueFilter = 'all';
    },

    // ── 详情：任务队列（新建 / 取消 / 重跑 / 跳详情） ──

    toggleNewTask() {
      this.showNewTask = !this.showNewTask;
    },

    toggleNewTaskSkill(event) {
      var key = event.currentTarget.dataset.key;
      var row = this.skillRows.find(function (r) { return r.key === key; });
      if (!row) return;
      var i = this.newTaskForm.skills.findIndex(function (s) { return s.key === key; });
      if (i >= 0) this.newTaskForm.skills.splice(i, 1);
      else this.newTaskForm.skills.push({ key: key, sourceName: row.sourceName, path: row.path });
    },

    submitTask(event) {
      event.preventDefault();
      var f = this.newTaskForm;
      if (f.sessionMode !== 'new' && !f.fromTask.trim()) {
        window.alert('续用 / fork 需要选择来源 Task');
        return;
      }
      var spec = {
        input: { prompt: { text: f.prompt.trim() } },
        output: { schema: { type: 'object' } },
        capabilities: {
          environments: [{ name: 'mac', kind: 'computer-use' }],
          skills: f.skills.map(function (s) { return { source: s.sourceName, path: s.path }; })
        }
      };
      if (f.model.trim()) spec.model = f.model.trim();
      var body = { spec: spec, endpoints: { mac: this.route.focus } };
      if (f.sessionMode !== 'new') body.session = { fromTask: f.fromTask.trim(), mode: f.sessionMode };
      window.adminApi.post('/tasks', body).then((res) => {
        this.taskWarnings = (res && res.warnings) || [];
        this.showNewTask = false;
        this.newTaskForm = { prompt: '', model: '', skills: [], sessionMode: 'new', fromTask: '' };
        this.loadEndpointDetail(this.route.focus);
      }).catch((e) => {
        window.alert('派发失败：' + this.errText(e));
      });
    },

    cancelTask(event) {
      window.adminTasks.cancelTask.call(this, event);
    },

    restartTask(event) {
      window.adminTasks.restartTask.call(this, event);
    },

    openTaskFromEndpoint(event) {
      var id = event.currentTarget.dataset.taskId;
      location.hash = '#/tasks?focus=' + encodeURIComponent(id);
    },

    // ── 展示辅助 ──

    /** 列表/详情互斥（模板用；CSP 禁运算符）。 */
    get endpointListVisible() {
      return this.isEndpointsPage && !this.route.focus;
    },

    get endpointDetailVisible() {
      return this.isEndpointsPage && !!this.route.focus;
    },

    get endpointEmpty() {
      return !this.endpointRows.length;
    },

    get editHidden() {
      return !this.showEdit;
    },

    get noSkills() {
      return !this.skillRows.length;
    },

    get taskWarningsVisible() {
      return this.taskWarnings.length > 0;
    },

    get taskWarningsText() {
      return '创建警告：' + this.taskWarnings.join('；');
    },

    // 面板三态（模板只读；禁运算符）
    get statusPanelLoading() { return this.panels.status === 'loading'; },
    get statusPanelError() { return this.panels.status === 'error'; },
    get statusPanelErrText() { return this.panelErr.status; },
    get statusPanelFailed() { return !!(this.detail && this.panels.status !== 'ok'); },
    get lockPanelLoading() { return this.panels.lock === 'loading'; },
    get lockPanelError() { return this.panels.lock === 'error'; },
    get lockPanelErrText() { return this.panelErr.lock; },
    get mcpPanelLoading() { return this.panels.mcp === 'loading'; },
    get mcpPanelError() { return this.panels.mcp === 'error'; },
    get mcpPanelErrText() { return this.panelErr.mcp; },
    get tasksPanelLoading() { return this.panels.tasks === 'loading'; },
    get tasksPanelError() { return this.panels.tasks === 'error'; },
    get tasksPanelErrText() { return this.panelErr.tasks; },

    // 机器锁：表单与权限门控
    get lockFormShown() { return this.showLockForm; },
    get lockCanAcquire() { return this.lockCanRead && this.canDoScope('lock:write'); },
    get lockCanRelease() { return this.lockCanRead && this.canDoScope('lock:write'); },
    get lockCanAdmin() { return this.lockCanRead && this.canDoScope('lock:admin'); },
    get lockCanRead() { return this.canDoScope('lock:read'); },
    get lockReadHint() { return this.lockReadHintText; },
    get lockWriteHint() { return this.lockWriteHintText; },
    get lockAdminHint() { return this.lockAdminHintText; },
    get lockCredShown() { return !!this.lockAcquire; },
    get lockConflictShown() { return !!this.lockConflict; },
    get lockErrorShown() { return !!this.lockError; },
    get lockTipShown() { return !!this.lockTip; },
    get copyTipShown() { return !!this.copyTip; },
    get lockNoteCount() {
      return this.lockForm.note.length + '/' + NOTE_MAX_CHARS;
    },
    get lockFormOpen() { return this.lockForm.open; },

    /** scope 门控：手填令牌与鉴权关闭时无法判定，交后端执行。 */
    canDoScope(name) {
      if (window.adminApi.manualToken()) return true;
      var auth = window.agentAppAuth;
      if (!auth || typeof auth.hasScope !== 'function') return true;
      var mode = (this.authInfo && this.authInfo.mode) || 'disabled';
      if (mode !== 'enforced') return true;
      return auth.hasScope(name);
    },

    // 任务过滤
    get queueFilterKey() {
      return this.queueFilter;
    },
    get queueChips() {
      var self = this;
      var rows = this.detail ? this.detail.queue : [];
      var chips = [{ key: 'all', label: '全部', count: rows.length }];
      QUEUE_STATES.forEach(function (state) {
        var n = rows.filter(function (r) { return r.state === state; }).length;
        if (n || self.queueFilter === state) chips.push({ key: state, label: state, count: n });
      });
      return chips.map(function (c) {
        return {
          key: c.key,
          label: c.label,
          countText: String(c.count),
          cls: self.queueFilter === c.key ? 'chip on' : 'chip'
        };
      });
    },
    get filteredQueue() {
      var key = this.queueFilter;
      var rows = this.detail ? this.detail.queue : [];
      if (key === 'all') return rows;
      return rows.filter(function (r) { return r.state === key; });
    },
    get queueFilterEmpty() {
      return !!(this.detail && this.detail.hasQueue && !this.filteredQueue.length);
    },
    get queueFilterActive() {
      return this.queueFilter !== 'all';
    },

    isActiveTaskState(state) {
      return ACTIVE_STATES.indexOf(state) >= 0;
    },

    /** 「相对现在」的粗粒度文本（探活新鲜度用；30s 内视为新鲜）。 */
    agoText(iso) {
      if (!iso) return '—';
      var t = new Date(iso).getTime();
      if (isNaN(t)) return String(iso);
      var secs = Math.max(0, Math.round((Date.now() - t) / 1000));
      if (secs < 60) return secs + ' 秒前';
      if (secs < 3600) return Math.round(secs / 60) + ' 分钟前';
      return Math.round(secs / 3600) + ' 小时前';
    },

    isStale(iso) {
      if (!iso) return false;
      var t = new Date(iso).getTime();
      return !isNaN(t) && Date.now() - t > STALE_PONG_MS;
    },

    isPast(iso) {
      if (!iso) return false;
      var t = new Date(iso).getTime();
      return !isNaN(t) && t <= Date.now();
    },

    /** 到期倒计时文本（分秒粒度；已过给「已过期」）。 */
    remainingText(iso) {
      if (!iso) return '';
      var t = new Date(iso).getTime();
      if (isNaN(t)) return '';
      var left = Math.round((t - Date.now()) / 1000);
      if (left <= 0) return '已过期';
      var mins = Math.floor(left / 60);
      var secs = left % 60;
      if (mins >= 60) {
        var hours = Math.floor(mins / 60);
        return hours + ' 小时 ' + (mins % 60) + ' 分';
      }
      return mins + ' 分 ' + secs + ' 秒';
    },

    mcpUrl(endpointId) {
      return location.origin + '/mcp/endpoints/' + endpointId;
    }
