const html = fs.readFileSync('index.html', 'utf8');
const attrRe = /(?:x-show|x-if|x-text|x-model|x-for|:class|:disabled|:title|:checked|:value|:maxlength|:data-[a-z-]+|@click(?:\.self|\.prevent)?|@submit(?:\.prevent)?|@change)="([^"]*)"/g;
const forRe = /x-for="([A-Za-z_$][\w$]*)\s+in\s+([^"]+)"/g;
