  if (/^[A-Za-z_$][\w$]*\s+in\s+/.test(expr)) continue;  // x-for 自身：别名
  for (const piece of expr.split(/[^A-Za-z0-9_$.]/)) {
    if (!piece) continue;
    const root = piece.split('.')[0];
    if (!root || aliases.has(root)) continue;
    exprs.add(piece === root ? root : root + ' ▸ ' + piece);
  }
}
// 允许的根：合并组件成员 + alpine/magic 属性
const allowed = new Set(Object.getOwnPropertyNames(comp));
const magic = new Set(['$event', 'true', 'false', 'null', 'undefined', 'n']);
let bad = [];
for (const e of exprs) {
  const root = e.split(' ')[0];
  if (!allowed.has(root) && !magic.has(root)) bad.push(e);
}
console.log('component 成员数:', allowed.size);
console.log('模板引用根数:', exprs.size);
if (bad.length) { console.error('FAIL 未解析的模板引用:'); bad.forEach(b => console.error('  -', b)); process.exit(1); }
console.log('OK: 模板引用全部落在合并组件成员上');
