  function mergeComponent(target, source) {
    if (!source) return target;
    Object.getOwnPropertyNames(source).forEach(function (key) {
      Object.defineProperty(target, key, Object.getOwnPropertyDescriptor(source, key));
    });
    return target;
  }

  /** 装配组件（顶栏/核心 + 各页 mixin；每页一个文件）。 */
  function buildComponent() {
    var merged = mergeComponent({}, window.adminCore);
    mergeComponent(merged, window.adminEndpoints);
    mergeComponent(merged, window.adminEndpointLock);
    mergeComponent(merged, window.adminTasks);
    mergeComponent(merged, window.adminConfig);
    mergeComponent(merged, window.adminPlaceholders);
    return merged;
  }

  window.adminComponent = buildComponent;

  // 注册必须早于 Alpine 启动：本脚本（defer）在 alpine.min.js 之前
  // 执行，监听 alpine:init 由 Alpine 启动时同步触发（auto-start 由
  // 构建内置的 queueMicrotask 完成，不需要也不应手动 start）。
  document.addEventListener('alpine:init', function () {
    if (window.Alpine && window.adminComponent) {
      window.Alpine.data('adminApp', window.adminComponent);
    }
  });
})();

